import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 12,
            xp: 850,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { 
                    type: 'CYBER_SECURITY', 
                    accent: '#3b82f6', // Blue
                    author: "Security_Ops_AI",
                    q: "Phishing Vector", 
                    sub: "Sender domain 'goggle.com' requesting auth.", 
                    opts: ["Report & Block", "Reply to Verify"], 
                    correct: 0, 
                    stat: "98% Match" 
                },
                { 
                    type: 'SAFETY_PROTO', 
                    accent: '#f59e0b', // Amber
                    author: "Floor_Safety_Bot",
                    q: "Zone B Violation", 
                    sub: "Forklift active while pedestrian light red.", 
                    opts: ["Right of Way", "Halt & Log"], 
                    correct: 1, 
                    stat: "Critical" 
                },
                { 
                    type: 'DATA_PRIVACY', 
                    accent: '#10b981', // Emerald
                    author: "Compliance_Sentinel",
                    q: "PII Detected", 
                    sub: "Customer SSN found in 'Notes' field.", 
                    opts: ["Ignore", "Auto-Redact"], 
                    correct: 1, 
                    stat: "GDPR Risk" 
                },
                { 
                    type: 'ETHICS', 
                    accent: '#ec4899', // Pink
                    author: "HR_Policy_Core",
                    q: "Gift Policy", 
                    sub: "Vendor offers $500 tickets to playoff game.", 
                    opts: ["Decline", "Accept"], 
                    correct: 0, 
                    stat: "Policy Check" 
                }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.streak = 42;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            // ... (Other modes omitted for brevity, logic remains in 'render')
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "Flashcard" Learning Feed (Clean Technical Style) ---

                // 1. UPDATE STATE & PHYSICS
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];
                const nextCard = state.feedCards[(state.currentCardIndex + 1) % state.feedCards.length];

                // Card Dimensions
                const cardW = 220; // Narrower, cleaner
                const cardH = 340;
                const cardX = (w - cardW) / 2;
                const cardY = (h - cardH) / 2;

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    // Hover around title
                    state.cursor.targetX = w/2 + Math.sin(time) * 10;
                    state.cursor.targetY = cy - 20;

                    if (state.feedTimer > 100) { // Read time
                        state.feedState = 'selecting';
                    }
                } 
                else if (state.feedState === 'selecting') {
                    // Move to correct button
                    const btnH = 40;
                    const spacing = 10;
                    const btnBaseY = cardY + cardH - 110;
                    const btnY = btnBaseY + card.correct * (btnH + spacing) + btnH/2;

                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;

                    // Snap click when close
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 3) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;

                        // Burst Particles
                        for(let i=0; i<25; i++) {
                            state.particles.push({
                                x: state.cursor.x,
                                y: state.cursor.y,
                                vx: (Math.random()-0.5) * 8,
                                vy: (Math.random()-0.5) * 8,
                                life: 1.0,
                                color: card.accent
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 60) { // Wait 1s viewing result
                        state.feedState = 'swiping';
                        state.cursor.targetY = h + 50; // Move out of way
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    // Slide Card Up and Fade
                    state.swipeOffset += ( -h/1.5 - state.swipeOffset) * 0.1;

                    // Reset
                    if (Math.abs(state.swipeOffset + h/1.5) < 10) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.x = w/2 + 100;
                        state.cursor.y = h + 50; 
                    }
                }

                // Cursor Physics
                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.2;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.2;

                // -- RENDER --

                // 1. Clean Technical Background
                ctx.fillStyle = '#050505';
                ctx.fillRect(0, 0, w, h);

                // Subtle Grid
                ctx.strokeStyle = 'rgba(255,255,255,0.03)';
                ctx.lineWidth = 1;
                const gridSize = 40;
                const offset = (time * 10) % gridSize;
                for(let x=0; x<w; x+=gridSize) {
                    ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,h); ctx.stroke();
                }
                for(let y=offset; y<h; y+=gridSize) {
                    ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y); ctx.stroke();
                }

                // 2. Draw Stack (Next Card) - Static behind
                if (state.feedState !== 'swiping' || state.swipeOffset > -50) {
                    ctx.save();
                    ctx.translate(w/2, h/2);
                    ctx.scale(0.9, 0.9);
                    ctx.translate(-w/2, -h/2);

                    ctx.fillStyle = '#111';
                    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
                    ctx.beginPath(); ctx.roundRect(cardX, cardY + 20, cardW, cardH, 16); ctx.fill(); ctx.stroke();
                    ctx.restore();
                }

                // 3. Active Card
                ctx.save();
                // Apply swipe transform only to active card
                ctx.translate(0, state.swipeOffset);
                const cardAlpha = 1 - Math.abs(state.swipeOffset) / (h/2);
                ctx.globalAlpha = Math.max(0, cardAlpha);

                // Card Body (Glass/Tech look)
                const grad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
                grad.addColorStop(0, '#161618');
                grad.addColorStop(1, '#0a0a0c');
                ctx.fillStyle = grad;

                ctx.shadowColor = 'rgba(0,0,0,0.5)'; ctx.shadowBlur = 20; ctx.shadowOffsetY = 10;
                ctx.beginPath(); ctx.roundRect(cardX, cardY, cardW, cardH, 16); ctx.fill();
                ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;

                // Card Border (Accent glow at top)
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                ctx.stroke();

                // Accent Bar
                ctx.fillStyle = card.accent;
                ctx.beginPath(); 
                // Top accent line inside rounded rect
                ctx.fillRect(cardX + 16, cardY + 16, 40, 2);

                // CONTENT
                ctx.textAlign = 'left';

                // Tag
                ctx.fillStyle = card.accent;
                ctx.font = 'bold 9px monospace';
                ctx.fillText(card.type, cardX + 16, cardY + 30);

                // Stat
                ctx.textAlign = 'right';
                ctx.fillStyle = 'rgba(255,255,255,0.3)';
                ctx.fillText(card.stat, cardX + cardW - 16, cardY + 30);

                // Question
                ctx.textAlign = 'left';
                ctx.fillStyle = '#fff';
                ctx.font = 'bold 18px sans-serif'; 
                // Wrap text manually if needed, for now simplified
                ctx.fillText(card.q, cardX + 16, cardY + 70);

                // Subtext
                ctx.fillStyle = 'rgba(255,255,255,0.5)';
                ctx.font = '11px sans-serif';
                // Simple wrapping logic for subtext
                const words = card.sub.split(' ');
                let line = '';
                let ly = cardY + 90;
                for(let n = 0; n < words.length; n++) {
                    const testLine = line + words[n] + ' ';
                    const metrics = ctx.measureText(testLine);
                    if (metrics.width > cardW - 32 && n > 0) {
                        ctx.fillText(line, cardX + 16, ly);
                        line = words[n] + ' ';
                        ly += 16;
                    } else {
                        line = testLine;
                    }
                }
                ctx.fillText(line, cardX + 16, ly);

                // Buttons
                const btnH = 40;
                const spacing = 10;
                const btnBaseY = cardY + cardH - 110;

                card.opts.forEach((opt: string, i: number) => {
                    const btnY = btnBaseY + i * (btnH + spacing);
                    const isCorrect = i === card.correct;
                    const isRevealed = state.feedState === 'feedback' || state.feedState === 'swiping';

                    let bg = 'rgba(255,255,255,0.05)';
                    let border = 'rgba(255,255,255,0.1)';
                    let text = 'rgba(255,255,255,0.7)';

                    if (isRevealed) {
                        if (isCorrect) {
                            bg = `${card.accent}33`; // 20% opacity hex
                            border = card.accent;
                            text = '#fff';
                        } else {
                            bg = 'rgba(255,255,255,0.02)';
                            text = 'rgba(255,255,255,0.2)';
                        }
                    }

                    // Button Rect
                    ctx.fillStyle = bg;
                    ctx.strokeStyle = border;
                    ctx.lineWidth = 1;
                    ctx.beginPath(); ctx.roundRect(cardX + 16, btnY, cardW - 32, btnH, 8); 
                    ctx.fill(); ctx.stroke();

                    // Text
                    ctx.fillStyle = text;
                    ctx.font = 'bold 11px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(opt, cx, btnY + 24);

                    // Checkmark if correct and revealed
                    if (isRevealed && isCorrect) {
                        ctx.fillStyle = card.accent;
                        ctx.beginPath(); ctx.arc(cardX + cardW - 32, btnY + 20, 3, 0, Math.PI*2); ctx.fill();
                    }
                });

                // HUD: Streak Counter (Floating above card)
                if (state.feedState !== 'swiping') {
                    ctx.restore(); // Exit swipe transform for HUD
                    ctx.save();

                    const hudY = cardY - 40;
                    ctx.fillStyle = 'rgba(255,255,255,0.1)';
                    ctx.textAlign = 'center';
                    ctx.font = '10px monospace';
                    ctx.fillText(`KNOWLEDGE_AUGMENTATION // STREAK: ${state.streak}`, cx, hudY);

                    // Feedback Splash Text
                    if (state.feedState === 'feedback') {
                        ctx.fillStyle = card.accent;
                        ctx.font = 'bold 12px sans-serif';
                        ctx.fillText("MEMORY ENCODED", cx, cardY + cardH + 30);
                    }
                    ctx.restore();
                } else {
                    ctx.restore(); // Exit swipe transform
                }

                // 4. Particles (Overlay everything)
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.vx *= 0.9; // Friction
                    p.vy *= 0.9;
                    p.life -= 0.05;

                    if (p.life <= 0) {
                        state.particles.splice(i, 1);
                        continue;
                    }

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 2, 2); 
                }
                ctx.globalAlpha = 1;

                // 5. Cursor
                if (state.feedState !== 'swiping') {
                    // Draw clean cursor
                    ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                    ctx.fillStyle = '#fff';
                    ctx.beginPath();
                    ctx.moveTo(state.cursor.x, state.cursor.y);
                    ctx.lineTo(state.cursor.x + 10, state.cursor.y + 10);
                    ctx.lineTo(state.cursor.x + 4, state.cursor.y + 10);
                    ctx.lineTo(state.cursor.x, state.cursor.y + 15);
                    ctx.fill();
                    ctx.shadowBlur = 0;

                    // Click Ripple
                    if (state.cursor.clicking) {
                        ctx.strokeStyle = '#fff';
                        ctx.lineWidth = 1;
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 15, 0, Math.PI*2); ctx.stroke();
                    }
                }
            }
            // ... (Existing render logic for other modes)
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                    state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                    // Find links from this start
                    const links = state.links.filter((l: any) => l.from === start.id);
                    links.forEach((l: any) => {
                        state.packets.push({
                            fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                        });
                    });
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                    grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                    ctx.strokeStyle = grad;

                    ctx.beginPath();
                    ctx.moveTo(n1.x, n1.y);
                    const midX = (n1.x + n2.x) / 2;
                    ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                    ctx.stroke();
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    const midX = (n1.x + n2.x) / 2;
                    const t = p.progress;
                    const invT = 1 - t;

                    const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                    const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 10; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        n2.active = 1.0;
                        const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                        nextLinks.forEach((l: any) => {
                            state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                        });
                        state.packets.splice(i, 1);
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLink = state.links.filter((l: any) => l.from === 0)[Math.floor(Math.random() * 6)];
                    if (startLink) {
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    ctx.moveTo(n1.x, n1.y);
                    ctx.lineTo(n2.x, n2.y);
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }
                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];
                    const currX = n1.x + (n2.x - n1.x) * p.t;
                    const currY = n1.y + (n2.y - n1.y) * p.t;
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                    ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                    ctx.shadowBlur = 0;
                    if (p.t >= 1) {
                        n2.active = 1;
                        if (n2.layer < 3 && Math.random() > 0.3) {
                            const nextLinks = state.links.map((l: any, idx: number) => ({...l, idx})).filter((l: any) => l.from === link.to);
                            if (nextLinks.length > 0) {
                                const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                            }
                        }
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            else if (mode === 'swarm') {
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if(b.x < inputEnd - 20) b.x += speed;
                    armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                    armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                    if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    armX = agent.targetBox.x + agent.targetBox.w/2;
                    armY = agent.targetBox.y;
                    if (agent.t >= 1) { agent.state = 'moving'; agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    const targetY = TARGET_YS[b.targetLane];

                    const startX = inputEnd - 20;
                    const targetX = outputStart + 20;

                    armX = startX + (targetX - startX) * t;
                    const midY = Math.min(beltY, targetY) - 60;
                    armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                    grabberGap = 0;
                    b.x = armX - b.w/2;
                    b.y = armY;

                    if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    armX = b.x + b.w/2;
                    armY = b.y;
                    grabberGap = 10 * Math.min(1, agent.t);

                    if (agent.t >= 1) {
                        b.state = 'conveyor_out';
                        b.y = TARGET_YS[b.targetLane];
                        agent.state = 'returning';
                        agent.targetBox = null;
                        agent.t = 0;
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            }
            else if (mode === 'translation') {
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        // Use alpha: true to allow the CSS background to show through if needed
        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- HELPER: POLYFILL FOR ROUND RECT (Fixes the "Broken Element" crash) ---
        const drawRoundRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) => {
            if (w < 2 * r) r = w / 2;
            if (h < 2 * r) r = h / 2;
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.arcTo(x + w, y, x + w, y + h, r);
            ctx.arcTo(x + w, y + h, x, y + h, r);
            ctx.arcTo(x, y + h, x, y, r);
            ctx.arcTo(x, y, x + w, y, r);
            ctx.closePath();
        };

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 12,
            xp: 850,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { 
                    type: 'CYBER_SEC', 
                    accent: '#3b82f6', // Blue
                    author: "Security_Ops_AI",
                    q: "Phishing Vector Detected", 
                    sub: "Sender 'goggle.com' requests auth.", 
                    opts: ["Block & Report", "Verify Sender"], 
                    correct: 0, 
                    stat: "98% Match" 
                },
                { 
                    type: 'SAFETY', 
                    accent: '#f59e0b', // Amber
                    author: "Floor_Safety_Bot",
                    q: "Zone B Violation", 
                    sub: "Forklift active. Pedestrian light red.", 
                    opts: ["Proceed", "Halt & Log"], 
                    correct: 1, 
                    stat: "Critical" 
                },
                { 
                    type: 'PRIVACY', 
                    accent: '#10b981', // Emerald
                    author: "Compliance_Sentinel",
                    q: "PII Detected in Logs", 
                    sub: "SSN found in 'Notes' field.", 
                    opts: ["Ignore", "Auto-Redact"], 
                    correct: 1, 
                    stat: "GDPR Risk" 
                },
                { 
                    type: 'ETHICS', 
                    accent: '#ec4899', // Pink
                    author: "HR_Policy_Core",
                    q: "Gift Policy Trigger", 
                    sub: "Vendor offers $500 tickets.", 
                    opts: ["Decline", "Accept"], 
                    correct: 0, 
                    stat: "Policy Check" 
                }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.streak = 42;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "Flashcard" Learning Feed (Polished) ---

                // 1. UPDATE STATE & PHYSICS
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                // Responsive Card Dimensions
                const cardW = Math.min(240, w * 0.85); 
                const cardH = 340;
                const cardX = (w - cardW) / 2;
                const cardY = (h - cardH) / 2;

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    // Hover around title
                    state.cursor.targetX = w/2 + Math.sin(time) * 15;
                    state.cursor.targetY = cardY + 60 + Math.cos(time * 1.5) * 5;

                    if (state.feedTimer > 120) { // Read time
                        state.feedState = 'selecting';
                    }
                } 
                else if (state.feedState === 'selecting') {
                    // Move to correct button
                    const btnH = 36;
                    const spacing = 12;
                    const btnBaseY = cardY + cardH - 110;
                    const btnY = btnBaseY + card.correct * (btnH + spacing) + btnH/2;

                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;

                    // Snap click when close
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 5) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;

                        // Burst Particles
                        for(let i=0; i<20; i++) {
                            state.particles.push({
                                x: state.cursor.x,
                                y: state.cursor.y,
                                vx: (Math.random()-0.5) * 8,
                                vy: (Math.random()-0.5) * 8,
                                life: 1.0,
                                color: card.accent
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 80) { // Wait 1s viewing result
                        state.feedState = 'swiping';
                        state.cursor.targetY = h + 100; // Move out of way
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    // Slide Card Up and Fade
                    state.swipeOffset += ( -h/1.2 - state.swipeOffset) * 0.12;

                    // Reset
                    if (Math.abs(state.swipeOffset + h/1.2) < 20) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.x = w/2 + 100;
                        state.cursor.y = h + 50; 
                    }
                }

                // Cursor Physics
                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.15;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.15;

                // -- RENDER --

                // 1. Clean Technical Background
                ctx.fillStyle = '#050505';
                ctx.fillRect(0, 0, w, h);

                // Moving Grid (Slow Pan)
                ctx.strokeStyle = 'rgba(255,255,255,0.04)';
                ctx.lineWidth = 1;
                const gridSize = 40;
                const gridOffsetX = (time * 5) % gridSize;
                const gridOffsetY = (time * 2) % gridSize;

                for(let x=gridOffsetX; x<w; x+=gridSize) {
                    ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,h); ctx.stroke();
                }
                for(let y=gridOffsetY; y<h; y+=gridSize) {
                    ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y); ctx.stroke();
                }

                // 2. Draw Stack (Next Card) - Static behind
                if (state.feedState !== 'swiping' || state.swipeOffset > -50) {
                    ctx.save();
                    ctx.translate(w/2, h/2);
                    ctx.scale(0.92, 0.92);
                    ctx.translate(-w/2, -h/2);

                    ctx.fillStyle = '#1a1a1c';
                    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                    drawRoundRect(ctx, cardX, cardY + 15, cardW, cardH, 16);
                    ctx.fill(); ctx.stroke();
                    ctx.restore();
                }

                // 3. Active Card
                ctx.save();
                // Apply swipe transform only to active card
                ctx.translate(0, state.swipeOffset);

                // Card Body (Glass/Tech look)
                const grad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
                grad.addColorStop(0, '#232325');
                grad.addColorStop(1, '#131315');
                ctx.fillStyle = grad;

                ctx.shadowColor = 'rgba(0,0,0,0.6)'; ctx.shadowBlur = 30; ctx.shadowOffsetY = 15;
                drawRoundRect(ctx, cardX, cardY, cardW, cardH, 16);
                ctx.fill();
                ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;

                // Border Highlight
                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.stroke();

                // Accent Bar
                ctx.fillStyle = card.accent;
                ctx.beginPath(); 
                ctx.rect(cardX + 24, cardY + 24, 30, 2);
                ctx.fill();

                // CONTENT
                ctx.textAlign = 'left';

                // Tag
                ctx.fillStyle = card.accent;
                ctx.font = 'bold 9px monospace';
                ctx.fillText(card.type, cardX + 24, cardY + 40);

                // Stat
                ctx.textAlign = 'right';
                ctx.fillStyle = 'rgba(255,255,255,0.3)';
                ctx.fillText(card.stat, cardX + cardW - 24, cardY + 40);

                // Question (Wrapped)
                ctx.textAlign = 'left';
                ctx.fillStyle = '#fff';
                ctx.font = 'bold 16px sans-serif'; 

                // Simple title wrap
                const titleWords = card.q.split(' ');
                let titleLine = '';
                let titleY = cardY + 80;
                for(let n = 0; n < titleWords.length; n++) {
                    const testLine = titleLine + titleWords[n] + ' ';
                    const metrics = ctx.measureText(testLine);
                    if (metrics.width > cardW - 48 && n > 0) {
                        ctx.fillText(titleLine, cardX + 24, titleY);
                        titleLine = titleWords[n] + ' ';
                        titleY += 20;
                    } else {
                        titleLine = testLine;
                    }
                }
                ctx.fillText(titleLine, cardX + 24, titleY);

                // Subtext (Wrapped)
                ctx.fillStyle = 'rgba(255,255,255,0.5)';
                ctx.font = '11px sans-serif';
                const words = card.sub.split(' ');
                let line = '';
                let ly = titleY + 25;
                for(let n = 0; n < words.length; n++) {
                    const testLine = line + words[n] + ' ';
                    const metrics = ctx.measureText(testLine);
                    if (metrics.width > cardW - 48 && n > 0) {
                        ctx.fillText(line, cardX + 24, ly);
                        line = words[n] + ' ';
                        ly += 16;
                    } else {
                        line = testLine;
                    }
                }
                ctx.fillText(line, cardX + 24, ly);

                // Buttons
                const btnH = 36;
                const spacing = 10;
                const btnBaseY = cardY + cardH - 110;

                card.opts.forEach((opt: string, i: number) => {
                    const btnY = btnBaseY + i * (btnH + spacing);
                    const isCorrect = i === card.correct;
                    const isRevealed = state.feedState === 'feedback' || state.feedState === 'swiping';

                    let bg = 'rgba(255,255,255,0.05)';
                    let border = 'rgba(255,255,255,0.1)';
                    let text = 'rgba(255,255,255,0.6)';

                    if (isRevealed) {
                        if (isCorrect) {
                            bg = `${card.accent}33`; // Hex opacity
                            border = card.accent;
                            text = '#fff';
                        } else {
                            bg = 'rgba(255,255,255,0.02)';
                            text = 'rgba(255,255,255,0.2)';
                        }
                    }

                    // Button Rect
                    ctx.fillStyle = bg;
                    ctx.strokeStyle = border;
                    ctx.lineWidth = 1;
                    drawRoundRect(ctx, cardX + 24, btnY, cardW - 48, btnH, 8);
                    ctx.fill(); ctx.stroke();

                    // Text
                    ctx.fillStyle = text;
                    ctx.font = 'bold 10px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(opt, cx, btnY + 22);

                    // Checkmark
                    if (isRevealed && isCorrect) {
                        ctx.fillStyle = card.accent;
                        ctx.beginPath(); ctx.arc(cardX + cardW - 40, btnY + 18, 3, 0, Math.PI*2); ctx.fill();
                    }
                });

                // HUD: Streak Counter
                if (state.feedState !== 'swiping') {
                    ctx.restore(); // Exit swipe for HUD
                    ctx.save();

                    const hudY = cardY - 30;
                    ctx.fillStyle = 'rgba(255,255,255,0.2)';
                    ctx.textAlign = 'center';
                    ctx.font = '10px monospace';
                    ctx.fillText(`KNOWLEDGE_AUGMENTATION // STREAK: ${state.streak}`, cx, hudY);

                    // Feedback Splash Text
                    if (state.feedState === 'feedback') {
                        ctx.fillStyle = card.accent;
                        ctx.font = 'bold 12px sans-serif';
                        ctx.fillText("MEMORY ENCODED", cx, cardY + cardH + 30);
                    }
                    ctx.restore();
                } else {
                    ctx.restore();
                }

                // 4. Particles
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.vx *= 0.9;
                    p.vy *= 0.9;
                    p.life -= 0.05;

                    if (p.life <= 0) {
                        state.particles.splice(i, 1);
                        continue;
                    }

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 2, 2); 
                }
                ctx.globalAlpha = 1;

                // 5. Cursor
                if (state.feedState !== 'swiping') {
                    // Shadow
                    ctx.shadowBlur = 8; ctx.shadowColor = 'rgba(255,255,255,0.5)';
                    ctx.fillStyle = '#fff';
                    ctx.beginPath();
                    ctx.moveTo(state.cursor.x, state.cursor.y);
                    ctx.lineTo(state.cursor.x + 12, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x + 4, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x, state.cursor.y + 18);
                    ctx.fill();
                    ctx.shadowBlur = 0;

                    // Click Ripple
                    if (state.cursor.clicking) {
                        ctx.strokeStyle = '#fff';
                        ctx.lineWidth = 1;
                        ctx.globalAlpha = 0.5;
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 20, 0, Math.PI*2); ctx.stroke();
                        ctx.globalAlpha = 1;
                    }
                }
            }
            // ... (Existing render logic for other modes)
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                    state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                    // Find links from this start
                    const links = state.links.filter((l: any) => l.from === start.id);
                    links.forEach((l: any) => {
                        state.packets.push({
                            fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                        });
                    });
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                    grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                    ctx.strokeStyle = grad;

                    ctx.beginPath();
                    ctx.moveTo(n1.x, n1.y);
                    const midX = (n1.x + n2.x) / 2;
                    ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                    ctx.stroke();
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    const midX = (n1.x + n2.x) / 2;
                    const t = p.progress;
                    const invT = 1 - t;

                    const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                    const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 10; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        n2.active = 1.0;
                        const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                        nextLinks.forEach((l: any) => {
                            state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                        });
                        state.packets.splice(i, 1);
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundRect(ctx, -40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundRect(ctx, -30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLink = state.links.filter((l: any) => l.from === 0)[Math.floor(Math.random() * 6)];
                    if (startLink) {
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    ctx.moveTo(n1.x, n1.y);
                    ctx.lineTo(n2.x, n2.y);
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }
                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];
                    const currX = n1.x + (n2.x - n1.x) * p.t;
                    const currY = n1.y + (n2.y - n1.y) * p.t;
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                    ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                    ctx.shadowBlur = 0;
                    if (p.t >= 1) {
                        n2.active = 1;
                        if (n2.layer < 3 && Math.random() > 0.3) {
                            const nextLinks = state.links.map((l: any, idx: number) => ({...l, idx})).filter((l: any) => l.from === link.to);
                            if (nextLinks.length > 0) {
                                const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                            }
                        }
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            else if (mode === 'swarm') {
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if(b.x < inputEnd - 20) b.x += speed;
                    armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                    armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                    if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    armX = agent.targetBox.x + agent.targetBox.w/2;
                    armY = agent.targetBox.y;
                    if (agent.t >= 1) { agent.state = 'moving'; agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    const targetY = TARGET_YS[b.targetLane];

                    const startX = inputEnd - 20;
                    const targetX = outputStart + 20;

                    armX = startX + (targetX - startX) * t;
                    const midY = Math.min(beltY, targetY) - 60;
                    armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                    grabberGap = 0;
                    b.x = armX - b.w/2;
                    b.y = armY;

                    if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    armX = b.x + b.w/2;
                    armY = b.y;
                    grabberGap = 10 * Math.min(1, agent.t);

                    if (agent.t >= 1) {
                        b.state = 'conveyor_out';
                        b.y = TARGET_YS[b.targetLane];
                        agent.state = 'returning';
                        agent.targetBox = null;
                        agent.t = 0;
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            }
            else if (mode === 'translation') {
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- HELPER: POLYFILL FOR ROUND RECT ---
        const drawRoundRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) => {
            if (w < 2 * r) r = w / 2;
            if (h < 2 * r) r = h / 2;
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.arcTo(x + w, y, x + w, y + h, r);
            ctx.arcTo(x + w, y + h, x, y + h, r);
            ctx.arcTo(x, y + h, x, y, r);
            ctx.arcTo(x, y, x + w, y, r);
            ctx.closePath();
        };

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0, rotation: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading',
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 12,
            xp: 850,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { type: 'CYBER_SEC', accent: '#3b82f6', q: "Phishing Vector", sub: "Sender 'goggle.com' requests auth.", opts: ["Block", "Verify"], correct: 0, stat: "98% Match" },
                { type: 'SAFETY', accent: '#f59e0b', q: "Zone B Violation", sub: "Forklift active. Light red.", opts: ["Proceed", "Halt"], correct: 1, stat: "Critical" },
                { type: 'PRIVACY', accent: '#10b981', q: "PII Detected", sub: "SSN found in 'Notes'.", opts: ["Ignore", "Redact"], correct: 1, stat: "GDPR Risk" },
            ],
            // Pacman State (Translation Mode)
            pacman: { x: 0, y: 0, dir: 0, mouth: 0, gridX: 1, gridY: 1, targetX: 1, targetY: 1 },
            maze: [],

            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;
            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;
            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;
            ctx.scale(dpr, dpr);
            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, rotation: 0 };

            state.feedState = 'reading';
            state.feedTimer = 0;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 60;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: (1 + Math.random()) * 0.5, // SLOWED DOWN (Data Strategy)
                        vy: (Math.random() - 0.5) * 0.2,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'translation') {
                // Initialize Maze for Pacman
                const cols = 15; const rows = 15;
                const cellW = w / cols; const cellH = h / rows;
                state.maze = [];
                for(let r=0; r<rows; r++) {
                    for(let c=0; c<cols; c++) {
                        // Simple procedural maze-like grid
                        const isWall = (r%2===0 && c%2===0) || (Math.random() > 0.8);
                        state.maze.push({
                            c, r, x: c*cellW + cellW/2, y: r*cellH + cellH/2, 
                            w: cellW, h: cellH, isWall, hasDot: !isWall
                        });
                    }
                }
                state.pacman = { x: cellW*1.5, y: cellH*1.5, gridX: 1, gridY: 1, dir: 0, speed: 0.1 };
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "Flashcard" Learning Feed ---
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                const cardW = Math.min(240, w * 0.85); 
                const cardH = 340;
                const cardX = (w - cardW) / 2;
                const cardY = (h - cardH) / 2;

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    state.cursor.targetX = w/2 + Math.sin(time) * 15;
                    state.cursor.targetY = cardY + 60 + Math.cos(time * 1.5) * 5;
                    if (state.feedTimer > 120) state.feedState = 'selecting';
                } 
                else if (state.feedState === 'selecting') {
                    const btnH = 36; const spacing = 12;
                    const btnBaseY = cardY + cardH - 110;
                    const btnY = btnBaseY + card.correct * (btnH + spacing) + btnH/2;
                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 5) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;
                        for(let i=0; i<20; i++) {
                            state.particles.push({
                                x: state.cursor.x, y: state.cursor.y,
                                vx: (Math.random()-0.5) * 8, vy: (Math.random()-0.5) * 8,
                                life: 1.0, color: card.accent
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 80) {
                        state.feedState = 'swiping';
                        state.cursor.targetY = h + 100;
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    state.swipeOffset += ( -h/1.2 - state.swipeOffset) * 0.12;
                    if (Math.abs(state.swipeOffset + h/1.2) < 20) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.x = w/2 + 100; state.cursor.y = h + 50; 
                    }
                }

                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.15;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.15;

                // Render Background
                ctx.fillStyle = '#050505'; ctx.fillRect(0, 0, w, h);
                ctx.strokeStyle = 'rgba(255,255,255,0.04)'; ctx.lineWidth = 1;
                const gridSize = 40;
                const gridOffsetX = (time * 5) % gridSize;
                for(let x=gridOffsetX; x<w; x+=gridSize) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,h); ctx.stroke(); }

                // Draw Stack
                if (state.feedState !== 'swiping' || state.swipeOffset > -50) {
                    ctx.save(); ctx.translate(w/2, h/2); ctx.scale(0.92, 0.92); ctx.translate(-w/2, -h/2);
                    ctx.fillStyle = '#1a1a1c'; ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                    drawRoundRect(ctx, cardX, cardY + 15, cardW, cardH, 16); ctx.fill(); ctx.stroke(); ctx.restore();
                }

                // Active Card
                ctx.save(); ctx.translate(0, state.swipeOffset);
                const grad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
                grad.addColorStop(0, '#232325'); grad.addColorStop(1, '#131315');
                ctx.fillStyle = grad;
                ctx.shadowColor = 'rgba(0,0,0,0.6)'; ctx.shadowBlur = 30; ctx.shadowOffsetY = 15;
                drawRoundRect(ctx, cardX, cardY, cardW, cardH, 16); ctx.fill();
                ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;
                ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.stroke();

                ctx.fillStyle = card.accent; ctx.beginPath(); ctx.rect(cardX + 24, cardY + 24, 30, 2); ctx.fill();
                ctx.textAlign = 'left'; ctx.font = 'bold 9px monospace'; ctx.fillText(card.type, cardX + 24, cardY + 40);

                ctx.fillStyle = '#fff'; ctx.font = 'bold 16px sans-serif'; 
                ctx.fillText(card.q, cardX + 24, cardY + 80);

                // Buttons
                const btnBaseY = cardY + cardH - 110;
                card.opts.forEach((opt: string, i: number) => {
                    const btnY = btnBaseY + i * 46;
                    const isCorrect = i === card.correct;
                    const isRevealed = state.feedState === 'feedback' || state.feedState === 'swiping';
                    let bg = 'rgba(255,255,255,0.05)';
                    if (isRevealed && isCorrect) bg = `${card.accent}33`;
                    ctx.fillStyle = bg; ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                    drawRoundRect(ctx, cardX + 24, btnY, cardW - 48, 36, 8); ctx.fill(); ctx.stroke();
                    ctx.fillStyle = '#fff'; ctx.font = 'bold 10px sans-serif'; ctx.textAlign = 'center';
                    ctx.fillText(opt, cx, btnY + 22);
                });
                ctx.restore();

                // Particles & Cursor
                state.particles.forEach((p:any) => {
                    p.x+=p.vx; p.y+=p.vy; p.vx*=0.9; p.vy*=0.9; p.life-=0.05;
                    ctx.fillStyle = p.color; ctx.globalAlpha = Math.max(0, p.life); ctx.fillRect(p.x,p.y,2,2);
                });
                ctx.globalAlpha=1;

                if (state.feedState !== 'swiping') {
                    ctx.shadowBlur = 8; ctx.shadowColor = 'rgba(255,255,255,0.5)';
                    ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 4, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                }
            }
            else if (mode === 'search') {
                // --- SLOWED DOWN DATA STRATEGY ---
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color); scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow; ctx.globalAlpha = 0.15; ctx.fillRect(processLine, 0, 60, h);
                ctx.fillStyle = color; ctx.globalAlpha = 0.8; ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx; // Slower movement
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h; if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)'; ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.05; // Smoother alignment
                        p.x += 0.5; // Slower post-process speed
                        ctx.fillStyle = color; ctx.globalAlpha = 1;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - 2, 20 * p.size, 4);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20; p.y = Math.random() * h;
                        p.vx = (1 + Math.random()) * 0.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'translation') {
                // --- PACMAN KNOWLEDGE CAPTURE ---
                const p = state.pacman;
                const cellW = state.maze[0].w;
                const cellH = state.maze[0].h;

                // Move Pacman
                if (Math.abs(p.targetX - p.gridX) < 0.1 && Math.abs(p.targetY - p.gridY) < 0.1) {
                    // Pick new target
                    const neighbors = [
                        {x: p.gridX+1, y: p.gridY}, {x: p.gridX-1, y: p.gridY},
                        {x: p.gridX, y: p.gridY+1}, {x: p.gridX, y: p.gridY-1}
                    ];
                    const valid = neighbors.filter(n => {
                        const cell = state.maze.find((c:any) => c.c === n.x && c.r === n.y);
                        return cell && !cell.isWall;
                    });
                    if (valid.length > 0) {
                        const next = valid[Math.floor(Math.random() * valid.length)];
                        p.targetX = next.x; p.targetY = next.y;
                    }
                }

                // Interpolate pos
                p.gridX += (p.targetX - p.gridX) * 0.1;
                p.gridY += (p.targetY - p.gridY) * 0.1;
                p.x = p.gridX * cellW + cellW/2;
                p.y = p.gridY * cellH + cellH/2;

                // Eat Dots
                state.maze.forEach((c: any) => {
                    if (c.hasDot) {
                        const dx = p.x - c.x; const dy = p.y - c.y;
                        if (Math.sqrt(dx*dx + dy*dy) < cellW/2) {
                            c.hasDot = false;
                            c.isStructure = true; // Turn into structured data
                        }
                    }
                });

                // Render Maze
                state.maze.forEach((c: any) => {
                    if (c.isWall) {
                        ctx.fillStyle = 'rgba(255,255,255,0.1)';
                        ctx.fillRect(c.x - c.w/2 + 2, c.y - c.h/2 + 2, c.w - 4, c.h - 4);
                    } else if (c.isStructure) {
                        ctx.strokeStyle = color;
                        ctx.lineWidth = 1;
                        ctx.strokeRect(c.x - 4, c.y - 4, 8, 8); // Captured knowledge
                    } else if (c.hasDot) {
                        ctx.fillStyle = 'rgba(255,255,255,0.3)';
                        ctx.beginPath(); ctx.arc(c.x, c.y, 2, 0, Math.PI*2); ctx.fill();
                    }
                });

                // Render Pacman
                ctx.fillStyle = color;
                const mouth = Math.abs(Math.sin(time * 10)) * 0.5;
                ctx.beginPath();
                ctx.arc(p.x, p.y, cellW/2 - 2, mouth, Math.PI * 2 - mouth);
                ctx.lineTo(p.x, p.y);
                ctx.fill();
            }
            else if (mode === 'swarm') {
                // --- BRIDGE AI: ROBOT ARM CONVEYOR ---
                const beltY = h * 0.75;
                const armBaseX = w * 0.5;
                const armBaseY = beltY - 20;

                // Spawn Boxes
                if (Math.random() > 0.98 && state.boxes.length < 5) {
                    const type = Math.floor(Math.random() * 3); // 0: HR, 1: OPS, 2: IT
                    state.boxes.push({ x: -20, y: beltY - 15, w: 20, h: 20, type, color: ['#ec4899', '#f59e0b', '#3b82f6'][type], held: false });
                }

                // Conveyor Belt
                ctx.fillStyle = '#333';
                ctx.fillRect(0, beltY, w, 10);
                ctx.fillStyle = '#555';
                for(let i=0; i<w; i+=40) {
                    ctx.fillRect((i + time * 50) % w, beltY, 2, 10);
                }

                // Bins
                const bins = [
                    { x: w * 0.2, label: "HR" }, { x: w * 0.5, label: "OPS" }, { x: w * 0.8, label: "IT" }
                ];
                bins.forEach(b => {
                    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
                    ctx.strokeRect(b.x - 20, h - 40, 40, 40);
                    ctx.fillStyle = 'rgba(255,255,255,0.5)';
                    ctx.font = '10px monospace'; ctx.textAlign = 'center';
                    ctx.fillText(b.label, b.x, h - 10);
                });

                // Robot Logic
                const agent = state.agent;
                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => !b.held && Math.abs(b.x - armBaseX) < 50);
                    if (target) {
                        agent.state = 'picking';
                        agent.target = target;
                        agent.t = 0;
                    }
                }

                let armX = armBaseX;
                let armY = armBaseY - 60;

                if (agent.state === 'picking') {
                    agent.t += 0.05;
                    armX = agent.target.x;
                    armY = agent.target.y;
                    if (agent.t >= 1) { agent.state = 'lifting'; agent.target.held = true; agent.t = 0; }
                } else if (agent.state === 'lifting') {
                    agent.t += 0.05;
                    armX = armBaseX;
                    armY = armBaseY - 100;
                    agent.target.x = armX; agent.target.y = armY;
                    if (agent.t >= 1) { agent.state = 'sorting'; agent.t = 0; }
                } else if (agent.state === 'sorting') {
                    agent.t += 0.05;
                    const bin = bins[agent.target.type];
                    armX = armBaseX + (bin.x - armBaseX) * agent.t;
                    armY = armBaseY - 100 + Math.sin(agent.t * Math.PI) * -20;
                    agent.target.x = armX; agent.target.y = armY;
                    if (agent.t >= 1) { agent.state = 'dropping'; agent.t = 0; }
                } else if (agent.state === 'dropping') {
                    agent.t += 0.1;
                    const bin = bins[agent.target.type];
                    armX = bin.x;
                    armY = h - 40;
                    agent.target.x = armX; agent.target.y = armY;
                    if (agent.t >= 1) { 
                        agent.state = 'idle'; 
                        state.boxes = state.boxes.filter((b:any) => b !== agent.target); 
                        agent.target = null;
                    }
                }

                // Draw Arm
                ctx.strokeStyle = color; ctx.lineWidth = 4;
                ctx.beginPath(); ctx.moveTo(armBaseX, armBaseY); 
                ctx.lineTo((armBaseX + armX)/2, armBaseY - 80); // Elbow
                ctx.lineTo(armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(armBaseX, armBaseY, 5, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 5, 0, Math.PI*2); ctx.fill();

                // Draw Boxes
                state.boxes.forEach((b: any) => {
                    if (!b.held) b.x += 1;
                    ctx.fillStyle = b.color;
                    ctx.fillRect(b.x - b.w/2, b.y - b.h, b.w, b.h);
                });
            }
            // ... (Other modes: logic, core, etc. preserved implicitly or added if missing)

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

export const LogisticsHeroVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let width = 0;
        let height = 0;
        let frameId: number;
        let time = 0;

        const COLS = 40; 
        const ROWS = 20;
        const PARTICLE_COUNT = COLS * ROWS; 
        const CAM_Z = 1200;
        const PHASE_DURATION = 800; 
        const TRANSITION_SPEED = 0.025;

        const P_STRIDE = 7;
        const data = new Float32Array(PARTICLE_COUNT * P_STRIDE);
        const projX = new Float32Array(PARTICLE_COUNT);
        const projY = new Float32Array(PARTICLE_COUNT);
        const projScale = new Float32Array(PARTICLE_COUNT);

        let phase = 0; 
        let phaseTimer = 0;

        const setTargetPlane = () => {
            const spacingX = 45;
            const spacingY = 45;
            const offsetX = (COLS * spacingX) / 2;
            const offsetY = (ROWS * spacingY) / 2;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                data[idx+3] = col * spacingX - offsetX;
                data[idx+4] = row * spacingY - offsetY;
                data[idx+5] = Math.sin(col * 0.2) * 40 + Math.cos(row * 0.2) * 40;
            }
        };

        const setTargetSphere = () => {
            const radius = 300;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const lat = (row / (ROWS - 1)) * Math.PI - Math.PI / 2;
                const lon = (col / (COLS - 1)) * Math.PI * 2;
                data[idx+3] = radius * Math.cos(lat) * Math.cos(lon);
                data[idx+4] = radius * Math.sin(lat);
                data[idx+5] = radius * Math.cos(lat) * Math.sin(lon);
            }
        };

        const setTargetTorus = () => {
            const R = 260; const r = 90;
            for(let i=0; i<PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const u = (col / COLS) * Math.PI * 2;
                const v = (row / ROWS) * Math.PI * 2;
                data[idx+3] = (R + r * Math.cos(v)) * Math.cos(u);
                data[idx+4] = (R + r * Math.cos(v)) * Math.sin(u);
                data[idx+5] = r * Math.sin(v);
            }
        };

        const updateTargets = () => {
             if (phase === 0) setTargetPlane();
             else if (phase === 1) setTargetSphere();
             else setTargetTorus();
        };

        // --- INITIALIZATION ---
        setTargetPlane();
        for(let i=0; i<PARTICLE_COUNT; i++) {
            const idx = i * P_STRIDE;
            // Clean Start: Match target exactly to avoid glitchy fly-in
            data[idx] = data[idx+3];
            data[idx+1] = data[idx+4];
            data[idx+2] = data[idx+5]; 

            const rand = Math.random();
            data[idx+6] = rand > 0.9 ? 1 : (rand > 0.7 ? 2 : 0);
        }

        const render = () => {
            time += 0.015;
            phaseTimer++;
            if (phaseTimer > PHASE_DURATION) {
                phaseTimer = 0;
                phase = (phase + 1) % 3;
                updateTargets();
            }

            ctx.fillStyle = '#020202';
            ctx.fillRect(0, 0, width, height);

            const cx = width * 0.75;
            const cy = height * 0.5;

            const rotY = time * 0.2;
            const rotX = Math.sin(time * 0.15) * 0.2;
            const cosY = Math.cos(rotY), sinY = Math.sin(rotY);
            const cosX = Math.cos(rotX), sinX = Math.sin(rotX);

            for (let i = 0; i < PARTICLE_COUNT; i++) {
                const idx = i * P_STRIDE;
                data[idx] += (data[idx+3] - data[idx]) * TRANSITION_SPEED;
                data[idx+1] += (data[idx+4] - data[idx+1]) * TRANSITION_SPEED;
                data[idx+2] += (data[idx+5] - data[idx+2]) * TRANSITION_SPEED;

                let x = data[idx];
                let y = data[idx+1];
                let z = data[idx+2];

                if (phase === 0) z += Math.sin(x * 0.03 + time * 4) * 20;

                let x1 = x * cosY - z * sinY;
                let z1 = z * cosY + x * sinY;
                let y1 = y * cosX - z1 * sinX;
                let z2 = z1 * cosX + y * sinX;

                const scale = CAM_Z / (CAM_Z + z2);
                projScale[i] = scale;

                if (scale > 0) {
                    projX[i] = cx + x1 * scale;
                    projY[i] = cy + y1 * scale;
                }
            }

            ctx.beginPath();
            ctx.strokeStyle = 'rgba(6, 182, 212, 0.12)'; 
            ctx.lineWidth = 0.8; 

            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const i = r * COLS + c;
                    if (projScale[i] <= 0) continue;

                    if (c < COLS - 1) {
                        const right = i + 1;
                        if (projScale[right] > 0) {
                            const distSq = (projX[i] - projX[right])**2 + (projY[i] - projY[right])**2;
                            if (distSq < 20000) {
                                ctx.moveTo(projX[i], projY[i]);
                                ctx.lineTo(projX[right], projY[right]);
                            }
                        }
                    }
                    if (r < ROWS - 1) {
                        const down = i + COLS;
                        if (projScale[down] > 0) {
                            const distSq = (projX[i] - projX[down])**2 + (projY[i] - projY[down])**2;
                            if (distSq < 20000) {
                                ctx.moveTo(projX[i], projY[i]);
                                ctx.lineTo(projX[down], projY[down]);
                            }
                        }
                    }
                }
            }
            ctx.stroke();

            const drawBatch = (color: string, typeVal: number) => {
                ctx.fillStyle = color;
                ctx.beginPath();
                for (let i = 0; i < PARTICLE_COUNT; i++) {
                    if (Math.abs(data[i * P_STRIDE + 6] - typeVal) > 0.1) continue;
                    if (projScale[i] <= 0) continue;
                    const size = (1.5 + Math.sin(time * 5 + i) * 0.5) * projScale[i];
                    ctx.rect(projX[i] - size/2, projY[i] - size/2, size, size);
                }
                ctx.fill();
            };

            drawBatch('#06b6d4', 0); 
            drawBatch('#f59e0b', 1); 
            drawBatch('#ffffff', 2); 

            frameId = requestAnimationFrame(render);
        };

        const handleResize = () => {
            if (canvas.parentElement) {
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.parentElement.getBoundingClientRect();
                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);
                width = rect.width;
                height = rect.height;
            }
        };
        window.addEventListener('resize', handleResize);
        handleResize();
        render();

        return () => {
            window.removeEventListener('resize', handleResize);
            cancelAnimationFrame(frameId);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" style={{ width: '100%', height: '100%' }} />;
};

